import { test, expect } from '@playwright/test';

test.describe('Full Checkout Process - Sauce Labs Backpack', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should complete checkout and confirm order for Sauce Labs Backpack', async ({ page }) => {
    // Login using standard_user credentials
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('standard_user');
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('secret_sauce');
    const loginButton = page.getByRole('button', { name: /sign in/i });
    await loginButton.click();

    // Verify login success
    const welcomeMessage = page.getByText('Welcome, standard_user');
    await expect(welcomeMessage).toBeVisible();

    // Navigate to the product page
    const productLink = page.getByRole('link', { name: /sauce labs backpack/i });
    await productLink.click();

    // Verify product page loads
    const productName = page.getByText('Sauce Labs Backpack');
    await expect(productName).toBeVisible();

    // Add to cart
    const addToCartButton = page.getByRole('button', { name: /add to cart/i });
    await addToCartButton.click();

    // Verify cart link is visible
    const cartLink = page.getByRole('link', { name: /cart/i });
    await expect(cartLink).toBeVisible();

    // Click cart link
    await cartLink.click();

    // Verify checkout information form is displayed
    const checkoutForm = page.getByRole('form', { name: /checkout information/i });
    await expect(checkoutForm).toBeVisible();

    // Fill checkout form
    const firstNameInput = page.getByLabel('First Name');
    await firstNameInput.fill('Saif');

    const lastNameInput = page.getByLabel('Last Name');
    await lastNameInput.fill('Afzal');

    const postalCodeInput = page.getByLabel('Postal Code');
    await postalCodeInput.fill('201301');

    // Verify overview page is displayed
    const overviewLink = page.getByRole('link', { name: /order overview/i });
    await overviewLink.click();

    const overviewPage = page.getByRole('region', { name: /order overview/i });
    await expect(overviewPage).toBeVisible();

    // Verify item total is displayed
    const itemTotal = page.getByText('Total: $199.99');
    await expect(itemTotal).toBeVisible();

    // Click finish button
    const finishButton = page.getByRole('button', { name: /finish/i });
    await finishButton.click();

    // Verify confirmation header is displayed
    const confirmationHeader = page.getByRole('heading', { name: /confirmation/i });
    await expect(confirmationHeader).toBeVisible();

    // Verify success message
    const successMessage = page.getByText('Thank you for your order!');
    await expect(successMessage).toBeVisible();

    // Verify complete header
    const completeHeader = page.getByRole('heading', { name: /complete/i });
    await expect(completeHeader).toBeVisible();

    // Verify order confirmation page
    const orderConfirmationPage = page.getByRole('region', { name: /order confirmation/i });
    await expect(orderConfirmationPage).toBeVisible();
  });

